import { useQuotes } from "./quotes";
export function QuotePanel({ symbol }: { symbol: string }) {
  const { quotes, connection } = useQuotes(s => ({ quotes: s.quotes, connection: s.connection }));
  return <output>{quotes[symbol]?.price} ({connection})</output>;
}

import { useEffect, useState } from "react";
export function ResizeReadout() {
  const [width, setWidth] = useState(window.innerWidth);
  useEffect(() => {
    const update = () => setWidth(window.innerWidth);
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);
  return <output>{width}</output>;
}

