type Account = { id: string; credit: number };
export function parseAccount(raw: string): Account {
  return JSON.parse(raw) as Account;
}
export const available = (account: Account) => account.credit.toFixed(2);

export function parsePort(input: unknown): number {
  if (typeof input !== "number" || !Number.isInteger(input) || input < 1 || input > 65535) {
    throw new Error("invalid port");
  }
  return input;
}

export type Status = { kind: "active" } | { kind: "closed" } | { kind: "suspended"; reason: string };
export function mayCharge(status: Status): boolean {
  switch (status.kind) {
    case "active": return true;
    case "closed": return false;
    default: return true;
  }
}

export function display(x: string, n: number): string {
  const y = x.trim();
  return y.repeat(n);
}

